head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50306";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.list();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50306.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50306.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_1_onsubmit
 * @description form_1 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_1_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50306.form_1_onsubmit' }); }
};

/**
 * @method
 * @name rd_mode_onclick
 * @description rd_mode 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rd_mode_onclick = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.search(selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50306.rd_mode_onclick' }); }
};

/**
 * @method
 * @name img_25_onclick
 * @description img_25 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_25_onclick = async function(e){
    try {
        await scwin.addFaq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50306.img_25_onclick' }); }
};

/**
 * @method
 * @name img_26_onclick
 * @description img_26 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_26_onclick = async function(e){
    try {
        await scwin.addHelpClass()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50306.img_26_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_List_xhr
 * @description List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

/**
 * @method
 * @name tx_fn_Delete_xhr
 * @description Delete xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr", unresolved: "action:self_submit:tx_fn_Delete_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    scwin.form_listForm.action = "/filing/helpFaq.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "findHelpClasses");
    $c.util.getComponent('txt_sysListDiv').setValue(await scwin.tx_fn_List_xhr());
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (obj) {
    const aftExposrTp = obj.value;
    const befExposrTp = (obj.parentNode.data === null ? "" : obj.parentNode.data);
    if (befExposrTp !== aftExposrTp) {
        obj.parentNode.data = obj.value;
        await scwin.list();
    }
};

/**
 * @method
 * @name onEnter
 * @description on Enter 처리
 * @returns {void}
 * @hidden N
 */
scwin.onEnter = function () {
    /* empty */
};

/**
 * @method
 * @name content
 * @description content 처리
 * @param {String} helpClssId helpClssId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.content = async function (helpClssId) {
    const _url = "/filing/systemInfo.do?method=findSystemInfo&helpClssId=" + helpClssId;
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=700,height=300";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "sysInfoPop", popupName: "sysInfoPop", width: "700", height: "300" }, {});
};

/**
 * @method
 * @name addHelpClass
 * @description add Help Class 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addHelpClass = async function () {
    const _url = "/filing/updateHelpFaq.do?method=prepareUpdateHelpClass" + "&mode=create";
