    await $c.win.openPopup((function (__u) { let __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "helpClassPop", popupName: "helpClassPop", width: "600", height: "240" }, {});
};

/**
 * @method
 * @name modHelpClass
 * @description mod Help Class 처리
 * @param {String} helpClssId helpClssId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modHelpClass = async function (helpClssId) {
    const _url = "/filing/updateHelpFaq.do?method=prepareUpdateHelpClass" + "&helpClssId=" + helpClssId + "&mode=update";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "helpClassPop", popupName: "helpClassPop", width: "600", height: "280" }, {});
};

/**
 * @method
 * @name deleteListXhrReq
 * @description delete List Xhr Req 처리
 * @param {String} helpClssId helpClssId
 * @param {String} helpClssNm helpClssNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteListXhrReq = async function (helpClssId, helpClssNm) {
    const _confirm = await $c.win.confirm("도움말분류 '" + helpClssNm + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_ListXhrReq').set('helpClssId', helpClssId);
    scwin.form_listForm.action = "/filing/helpFaq.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "deleteHelpClass");
    $c.util.getComponent('txt_sysListDiv').setValue(await scwin.tx_fn_Delete_xhr());
};

/**
 * @method
 * @name findFaqs
 * @description find Faqs 처리
 * @param {String} helpClssId helpClssId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findFaqs = async function (helpClssId) {
    const winTitle = "FAQ 보기";
    const _url = "/filing/helpFaq.do?method=findHelpFaqs&helpClssId=" + helpClssId;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "faqPop", popupName: "faqPop", width: "700", height: "800" }, {});
};

/**
 * @method
 * @name addFaq
 * @description add Faq 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addFaq = async function () {
    const _url = "/filing/updateHelpFaq.do?method=prepareUpdateHelpFaq";
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=700,height=300";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "faqPop", popupName: "faqPop", width: "700", height: "660" }, {});
